vec3 hash3(float p) {
    vec3 p3 = fract(vec3(p) * vec3(0.1031, 0.11369, 0.13787));
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.xxy + p3.yzz) * p3.zyx);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.0);
    float time = iTime * 1.5;

    const int NUM_STARS = 400;
    const float FAR = 20.0;

    for (int i = 0; i < NUM_STARS; i++) {
        // Generate unique star parameters using hash function
        vec3 rand = hash3(float(i));

        // Calculate star position in 3D space
        float angle = rand.x * 6.2832;
        float radius = pow(rand.y, 0.5) * 0.4;
        float x = cos(angle) * radius;
        float y = sin(angle) * radius;
        float zPhase = rand.z * FAR;

        // Set star speed and calculate current Z position
        float speed = 0.5 + rand.x * 2.5;
        float z = FAR - mod(time * speed - zPhase, FAR);

        if (z < 0.3) continue; // Skip stars too close to camera

        // Project star to 2D screen space
        vec2 starPos = vec2(x, y) / z;
        float dist = length(uv - starPos);

        // Calculate size and brightness based on distance
        float starSize = 0.004 * (0.4 / z);
        float brightness = smoothstep(starSize, 0.0, dist);
        brightness *= 0.7 / (z * z); // Attenuate brightness with distance

        // Add subtle color variation
        vec3 starColor = mix(vec3(0.8, 0.9, 1.0), vec3(1.0, 0.9, 0.7), rand.y);
        col += starColor * brightness;
    }

    // Add radial fade at screen edges
    float vignette = 1.0 - smoothstep(0.5, 1.2, length(uv));
    col *= vignette * vignette;

    // Apply gamma correction
    col = pow(col, vec3(0.4545));

    fragColor = vec4(col, 1.0);
}
